local({
  how_long <- as.numeric(PREOUDERRM4a_1)
  when <- as.numeric(PREOUDERRM5a_1)
  case_when(how_long %in% 2:5 | when %in% 2:5 ~ "TRUE", how_long %in% 1 | when %in% 1 ~ "FALSE")
})

local({
  before <- as.numeric(PREKINDDUBBELLAGER)
  during <- as.numeric(PREKINDDUBBELMIDDELB)
  case_when(before > 1 | during > 1 ~ "TRUE", before == 1 & during == 1 ~ "FALSE")
})

local({
  days <- cbind(D1Gametijd, D2Gametijd, D3Gametijd, D4Gametijd, D5Gametijd, D6Gametijd, D7Gametijd)
  answered <- rowSums(!is.na(days))
  if_else(answered >= 4, rowMeans(days, na.rm = TRUE) / 60, NA_real_)
})
